-- Periksa hasil pemasangan: tiap baris cocok = 1; baris terakhir keluaran harus "SEMUA COCOK".
SELECT no_var, cocok FROM (
SELECT 4950 AS no_var, (SELECT COUNT(*) FROM abt_variabel v WHERE v.no_var = 4950 AND MD5(v.nama) = 'bf21baeb2cd0e9ef6c6a27193471c368' AND v.data_type = 'tanya_jawab' AND v.referensi = 98 AND v.multi_sidang = 'tanyajawab' AND EXISTS (SELECT 1 FROM abt_variabel s WHERE s.no_var = 6113 AND s.data_tabel <=> v.data_tabel AND s.data_kolom <=> v.data_kolom AND s.urutan_data <=> v.urutan_data AND s.sql_query <=> v.sql_query AND s.default_data <=> v.default_data AND s.locked <=> v.locked AND s.modifier <=> v.modifier)) AS cocok
UNION ALL
SELECT 4951 AS no_var, (SELECT COUNT(*) FROM abt_variabel v WHERE v.no_var = 4951 AND MD5(v.nama) = '8e598218f1a94c95679d58685d25f7df' AND v.data_type = 'tanya_jawab' AND v.referensi = 102 AND v.multi_sidang = 'tanyajawab' AND EXISTS (SELECT 1 FROM abt_variabel s WHERE s.no_var = 6112 AND s.data_tabel <=> v.data_tabel AND s.data_kolom <=> v.data_kolom AND s.urutan_data <=> v.urutan_data AND s.sql_query <=> v.sql_query AND s.default_data <=> v.default_data AND s.locked <=> v.locked AND s.modifier <=> v.modifier)) AS cocok
UNION ALL
SELECT 4952 AS no_var, (SELECT COUNT(*) FROM abt_variabel v WHERE v.no_var = 4952 AND MD5(v.nama) = 'cd5ad4755bca6dfd0c1907fdeac86028' AND v.data_type = 'tanya_jawab' AND v.referensi = 98 AND v.multi_sidang = 'keterangan' AND EXISTS (SELECT 1 FROM abt_variabel s WHERE s.no_var = 2019 AND s.data_tabel <=> v.data_tabel AND s.data_kolom <=> v.data_kolom AND s.urutan_data <=> v.urutan_data AND s.sql_query <=> v.sql_query AND s.default_data <=> v.default_data AND s.locked <=> v.locked AND s.modifier <=> v.modifier)) AS cocok
UNION ALL
SELECT 4953 AS no_var, (SELECT COUNT(*) FROM abt_variabel v WHERE v.no_var = 4953 AND MD5(v.nama) = '04b63245e34bcc12ac1ad445e74a2dcf' AND v.data_type = 'tanya_jawab' AND v.referensi = 102 AND v.multi_sidang = 'keterangan' AND EXISTS (SELECT 1 FROM abt_variabel s WHERE s.no_var = 2018 AND s.data_tabel <=> v.data_tabel AND s.data_kolom <=> v.data_kolom AND s.urutan_data <=> v.urutan_data AND s.sql_query <=> v.sql_query AND s.default_data <=> v.default_data AND s.locked <=> v.locked AND s.modifier <=> v.modifier)) AS cocok
) c;
SELECT IF(SUM(cocok) = 4 AND (SELECT COUNT(*) FROM abt_variabel WHERE no_var BETWEEN 4950 AND 4959) = 4, 'SEMUA COCOK', 'ADA YANG TIDAK COCOK') AS hasil FROM (
SELECT 4950 AS no_var, (SELECT COUNT(*) FROM abt_variabel v WHERE v.no_var = 4950 AND MD5(v.nama) = 'bf21baeb2cd0e9ef6c6a27193471c368' AND v.data_type = 'tanya_jawab' AND v.referensi = 98 AND v.multi_sidang = 'tanyajawab' AND EXISTS (SELECT 1 FROM abt_variabel s WHERE s.no_var = 6113 AND s.data_tabel <=> v.data_tabel AND s.data_kolom <=> v.data_kolom AND s.urutan_data <=> v.urutan_data AND s.sql_query <=> v.sql_query AND s.default_data <=> v.default_data AND s.locked <=> v.locked AND s.modifier <=> v.modifier)) AS cocok
